document.addEventListener("DOMContentLoaded",function(){var e=document.getElementById("select-all-categories");e&&e.addEventListener("click",function(){document.querySelectorAll(".category-checkbox").forEach(function(e){e.checked=!0})});var t=document.getElementById("deselect-all-categories");t&&t.addEventListener("click",function(){document.querySelectorAll(".category-checkbox").forEach(function(e){e.checked=!1})});var c=document.getElementById("toggle-parent-categories");c&&c.addEventListener("click",function(){document.querySelectorAll(".category-checkbox").forEach(function(e){e.checked="0"===e.getAttribute("data-level")})});var n=document.getElementById("category-search");n&&n.addEventListener("input",function(){var e=this.value.toLowerCase();document.querySelectorAll(".category-item").forEach(function(t){t.textContent.toLowerCase().includes(e)?t.style.display="":t.style.display="none"})});var o=document.querySelector('input[name="yali_enable_category_filter"]'),a=document.getElementById("category-selection-container");o&&a&&o.addEventListener("change",function(){a.style.display=this.checked?"block":"none"})});